(async () => {
  const tabs = [...document.querySelectorAll('.video-tabs .tab')];
  const cards = [...document.querySelectorAll('.video-card')];
  const total = cards.length;
  tabs.find(t => t.dataset.filter === 'Factory').click();
  await new Promise(r => setTimeout(r, 200));
  const visible = cards.filter(c => !c.hidden).length;
  cards.find(c => !c.hidden).click();
  await new Promise(r => setTimeout(r, 400));
  const modal = document.getElementById('vmodal');
  const cap = document.getElementById('vcap');
  const open = modal && !modal.hidden;
  if (modal) modal.querySelector('[data-vclose]').click();
  await new Promise(r => setTimeout(r, 200));
  return {total, factoryVisible: visible, modalOpened: open,
          caption: cap ? cap.textContent : '', closedAgain: modal ? modal.hidden : null};
})()
